def merge_records(primary, incoming):
    """Merge incoming sync records into the primary list, dropping duplicate contacts."""
    def is_empty(v):
        if v is None:
            return True
        if isinstance(v, str) and not v.strip():
            return True
        return False

    def get_richness(rec):
        exclude = {"email", "updated"}
        return sum(1 for k, v in rec.items() if k not in exclude and not is_empty(v))

    # We'll keep track of the best record for each email.
    # Key: lowercased email
    # Value: (record, is_primary)
    best_for_email = {}

    # To preserve the exact insertion order of first appearance of each contact.
    order = []
    seen = set()

    # Combine with a flag indicating if the record is from primary
    all_records = [(rec, True) for rec in primary] + [(rec, False) for rec in incoming]

    for rec, is_primary in all_records:
        email_lower = rec["email"].lower()

        if email_lower not in seen:
            seen.add(email_lower)
            order.append(email_lower)

        if email_lower not in best_for_email:
            best_for_email[email_lower] = (rec, is_primary)
        else:
            # Compare current best with the new record
            best_rec, best_is_primary = best_for_email[email_lower]

            rich_best = get_richness(best_rec)
            rich_new = get_richness(rec)

            # We want to decide if rec is better than best_rec
            replace = False
            if rich_new > rich_best:
                replace = True
            elif rich_new < rich_best:
                replace = False
            else:
                # Richness is equal
                if best_is_primary != is_primary:
                    # One is primary, one is incoming. We prefer the primary one.
                    # So we replace if the new one is primary and the old one is not.
                    if is_primary:
                        replace = True
                    else:
                        replace = False
                else:
                    # Both are primary or both are incoming
                    # We prefer the one with the newer updated timestamp
                    up_best = best_rec.get("updated", "")
                    up_new = rec.get("updated", "")
                    if up_new > up_best:
                        replace = True

            if replace:
                best_for_email[email_lower] = (rec, is_primary)

    # Reconstruct the output in insertion order
    out = [best_for_email[email_lower][0] for email_lower in order]
    return out

