def merge_records(primary, incoming):
    """Merge incoming sync records into the primary list, dropping duplicate contacts."""
    def is_empty(v):
        if v is None:
            return True
        if isinstance(v, str) and not v.strip():
            return True
        return False

    def get_richness(rec):
        exclude = {"email", "updated"}
        return sum(1 for k, v in rec.items() if k not in exclude and not is_empty(v))

    def get_key(rec):
        email = rec.get("email", "").lower()
        updated = rec.get("updated", "")
        date_str = updated[:10] if len(updated) >= 10 else updated
        return (email, date_str)

    best_for_key = {}
    order = []
    seen = set()

    all_records = [(rec, True) for rec in primary] + [(rec, False) for rec in incoming]

    for rec, is_primary in all_records:
        key = get_key(rec)

        if key not in seen:
            seen.add(key)
            order.append(key)

        if key not in best_for_key:
            best_for_key[key] = (rec, is_primary)
        else:
            best_rec, best_is_primary = best_for_key[key]

            rich_best = get_richness(best_rec)
            rich_new = get_richness(rec)

            replace = False
            if rich_new > rich_best:
                replace = True
            elif rich_new < rich_best:
                replace = False
            else:
                # Richness is equal
                if best_is_primary != is_primary:
                    # One is primary, one is incoming. We prefer the primary one.
                    if is_primary:
                        replace = True
                    else:
                        replace = False
                else:
                    # Both are primary or both are incoming
                    # We prefer the one with the newer updated timestamp
                    up_best = best_rec.get("updated", "")
                    up_new = rec.get("updated", "")
                    if up_new > up_best:
                        replace = True

            if replace:
                best_for_key[key] = (rec, is_primary)

    out = [best_for_key[key][0] for key in order]
    return out

