def plan_waves(services):
    """Group services into ordered deployment waves (lists of service names)."""
    if not services:
        return []

    # Map name to service
    service_names = {s["name"] for s in services}

    # Adjacency list and in-degrees
    adj = {s["name"]: [] for s in services}
    in_degree = {s["name"]: 0 for s in services}

    for s in services:
        u = s["name"]
        for dep in s.get("deps", []):
            if dep in service_names:
                adj[dep].append(u)
                in_degree[u] += 1

    # Build waves level-by-level
    waves = []
    current_wave = sorted([u for u in service_names if in_degree[u] == 0])

    while current_wave:
        waves.append(current_wave)
        next_wave_candidates = []
        for u in current_wave:
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    next_wave_candidates.append(v)
        current_wave = sorted(next_wave_candidates)

    # If there are still services left (due to cycles), append them to a final wave.
    placed_services = {name for wave in waves for name in wave}
    remaining = sorted([u for u in service_names if u not in placed_services])
    if remaining:
        waves.append(remaining)

    return waves

