def _plan_group(group_services):
    if not group_services:
        return []

    # Map name to service
    service_names = {s["name"] for s in group_services}

    # Adjacency list and in-degrees
    adj = {s["name"]: [] for s in group_services}
    in_degree = {s["name"]: 0 for s in group_services}

    for s in group_services:
        u = s["name"]
        for dep in s.get("deps", []):
            if dep in service_names:
                adj[dep].append(u)
                in_degree[u] += 1

    # Helper to sort a list of service names by (tier, name)
    service_map = {s["name"]: s for s in group_services}
    def sort_key(name):
        s = service_map[name]
        return (s.get("tier", 0), name)

    # Build waves level-by-level
    waves = []
    current_wave = sorted([u for u in service_names if in_degree[u] == 0], key=sort_key)

    while current_wave:
        waves.append(current_wave)
        next_wave_candidates = []
        for u in current_wave:
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    next_wave_candidates.append(v)
        current_wave = sorted(next_wave_candidates, key=sort_key)

    # If there are still services left (due to cycles), append them to a final wave.
    placed_services = {name for wave in waves for name in wave}
    remaining = sorted([u for u in service_names if u not in placed_services], key=sort_key)
    if remaining:
        waves.append(remaining)

    return waves


def plan_waves(services):
    """Group services into ordered deployment waves (lists of service names)."""
    if not services:
        return []

    canaries = [s for s in services if s.get("canary", False)]
    non_canaries = [s for s in services if not s.get("canary", False)]

    canary_waves = _plan_group(canaries)
    non_canary_waves = _plan_group(non_canaries)

    return canary_waves + non_canary_waves
