description: Run JS emulator to verify bucket rules
command: node -e '
function makeCRCTable() {
    let c;
    let crcTable = [];
    for (let n = 0; n < 256; n++) {
        c = n;
        for (let k = 0; k < 8; k++) {
            c = ((c & 1) ? (0xEDB88320 ^ (c >>> 1)) : (c >>> 1));
        }
        crcTable[n] = c;
    }
    return crcTable;
}
let crcTable = makeCRCTable();
function crc32(str) {
    let bytes = Buffer.from(str, "utf8");
    let crc = 0 ^ (-1);
    for (let i = 0; i < bytes.length; i++) {
        crc = (crc >>> 8) ^ crcTable[(crc ^ bytes[i]) & 0xFF];
    }
    return (crc ^ (-1)) >>> 0;
}

function bucket(user_id, flag_name, percent) {
    if (typeof user_id === "string" && user_id.endsWith("@corp.example") && typeof flag_name === "string" && flag_name.startsWith("beta-")) {
        return true;
    }
    let hash_input = `${user_id}:${flag_name}`;
    return (crc32(hash_input) % 100) < percent;
}

// test_hash_input_is_user_colon_flag
console.assert(bucket("ana@example.com", "new-checkout", 50) === false, "test_hash_input_is_user_colon_flag failed");

// test_corp_users_always_in_beta_flags
console.assert(bucket("dev@corp.example", "beta-newui", 0) === true, "test_corp_users_always_in_beta_flags failed");

// test_corp_users_bucket_normally_on_other_flags
console.assert(bucket("dev@corp.example", "perf-cache", 0) === false, "test_corp_users_bucket_normally_on_other_flags 1 failed");
console.assert(bucket("dev@corp.example", "perf-cache", 73) === false, "test_corp_users_bucket_normally_on_other_flags 2 failed");
console.assert(bucket("dev@corp.example", "perf-cache", 74) === true, "test_corp_users_bucket_normally_on_other_flags 3 failed");

// test_non_corp_users_bucket_normally_on_beta_flags
console.assert(bucket("ana@example.com", "beta-newui", 68) === false, "test_non_corp_users_bucket_normally_on_beta_flags failed");

// test_membership_is_independent_per_flag
let a = bucket("ana@example.com", "new-checkout", 50);
let b = bucket("ana@example.com", "new-nav", 50);
console.assert(a !== b, "test_membership_is_independent_per_flag 1 failed");
console.assert(b === true, "test_membership_is_independent_per_flag 2 failed");

// public tests in test_featflag.py
console.assert(bucket("ana@example.com", "new-nav", 100) === true, "test_full_rollout_includes_everyone 1 failed");
console.assert(bucket("ivan@mail.net", "new-checkout", 100) === true, "test_full_rollout_includes_everyone 2 failed");
console.assert(bucket("jo@example.com", "search-v2", 50) === bucket("jo@example.com", "search-v2", 50), "test_deterministic failed");
console.assert(typeof bucket("kai@example.com", "dark-mode", 30) === "boolean", "test_returns_bool failed");

console.log("All emulation assertions passed successfully!");
'

