content: """Egress allowlist matching."""
import ipaddress


def is_ip_address(h):
    try:
        ipaddress.ip_address(h)
        return True
    except ValueError:
        return False


def normalize(name):
    name = name.lower()
    if name.endswith('.'):
        name = name[:-1]
    return name


def is_allowed(host, allowlist):
    """Check an outbound host against the egress allowlist."""
    host_norm = normalize(host)
    is_ip = is_ip_address(host_norm)

    for entry in allowlist:
        entry_norm = normalize(entry)

        if entry_norm.startswith("*."):
            if is_ip:
                # Wildcards do not apply to IP address literals
                continue
            suffix = entry_norm[2:]
            expected_suffix = "." + suffix
            if host_norm.endswith(expected_suffix):
                prefix = host_norm[:-len(expected_suffix)]
                # Wildcard must match exactly one subdomain label
                if prefix and "." not in prefix:
                    return True
        else:
            if host_norm == entry_norm:
                return True

    return False

