def apply_updates(base, updates):
    if isinstance(base, dict) and isinstance(updates, dict):
        result = dict(base)
        for k, v in updates.items():
            if k in result:
                result[k] = apply_updates(result[k], v)
            else:
                result[k] = v
        return result
    elif isinstance(base, list) and isinstance(updates, list):
        merged = list(base)
        for item in updates:
            if item not in merged:
                merged.append(item)
        return merged
    else:
        return updates

