def _redact(val):
    if isinstance(val, collections.abc.Mapping):
        res = {}
        for k, v in val.items():
            res[k] = mask_value(k, v)
        return res
    elif isinstance(val, list):
        return [_redact(item) for item in val]
    elif isinstance(val, tuple):
        return tuple(_redact(item) for item in val)
    elif isinstance(val, set):
        return {_redact(item) for item in val}
    else:
        return val


def mask_value(k, v):
    if not isinstance(k, str):
        return _redact(v)

    k_lower = k.lower()
    k_norm = k_lower.replace("-", "").replace("_", "").replace(" ", "")

    if any(t in k_lower or t in k_norm for t in ("card_number", "cardnumber")):
        if isinstance(v, (str, int)):
            return "***" + str(v)[-4:]
        else:
            return "***"

    if any(t in k_lower or t in k_norm for t in ("password", "token", "key", "secret", "ssn", "passwd")):
        return "***"

    return _redact(v)
