newString: """Redact sensitive fields from log events."""

from collections.abc import Mapping, Sequence, Set
from boltons.iterutils import remap


def redact(event):
    """Mask sensitive fields in a log event."""
    if not isinstance(event, (Mapping, Sequence, Set)) or isinstance(event, (str, bytes)):
        return event

    def normalize_key(key):
        if isinstance(key, bytes):
            try:
                k_str = key.decode("utf-8", errors="ignore")
            except Exception:
                k_str = str(key)
        else:
            k_str = str(key)
        return k_str.lower().replace("-", "_")

    def visit(path, key, value):
        if not isinstance(key, (str, bytes)):
            return True

        norm_key = normalize_key(key)

        if norm_key.endswith("card_number"):
            if isinstance(value, (Mapping, Sequence)) and not isinstance(value, (str, bytes)):
                return key, "***"
            if value is None:
                return key, "***"
            return key, f"***{str(value)[-4:]}"

        if (
            norm_key.endswith("password") or
            norm_key.endswith("token") or
            norm_key.endswith("key") or
            norm_key.endswith("ssn") or
            norm_key.endswith("secret") or
            norm_key.endswith("credential") or
            norm_key.endswith("credentials")
        ):
            return key, "***"

        return True

    return remap(event, visit=visit)
