content: """SLA downtime accounting."""
from datetime import datetime, timedelta


def _t(s):
    return datetime.fromisoformat(s)


def downtime_minutes(incidents, maintenance):
    """Total SLA downtime in minutes for a billing period."""
    # 1. Parse and sort incidents
    sorted_inc = sorted([(_t(inc["start"]), _t(inc["end"])) for inc in incidents], key=lambda x: x[0])

    # 2. Merge overlapping incident intervals
    merged_inc = []
    for start, end in sorted_inc:
        if not merged_inc:
            merged_inc.append((start, end))
        else:
            last_start, last_end = merged_inc[-1]
            if start <= last_end:
                merged_inc[-1] = (last_start, max(last_end, end))
            else:
                merged_inc.append((start, end))

    # 3. Filter out sub-minute blips (less than 1 minute)
    filtered_inc = [(start, end) for start, end in merged_inc if (end - start).total_seconds() >= 60.0]

    # 4. Filter and merge valid maintenance windows
    valid_maint = []
    for m in maintenance:
        announced_at_str = m.get("announced_at")
        if not announced_at_str:
            continue
        m_start, m_end = _t(m["start"]), _t(m["end"])
        if (m_start - _t(announced_at_str)) >= timedelta(hours=24):
            valid_maint.append((m_start, m_end))

    sorted_maint = sorted(valid_maint, key=lambda x: x[0])
    merged_maint = []
    for start, end in sorted_maint:
        if not merged_maint:
            merged_maint.append((start, end))
        else:
            last_start, last_end = merged_maint[-1]
            if start <= last_end:
                merged_maint[-1] = (last_start, max(last_end, end))
            else:
                merged_maint.append((start, end))

    # 5. Calculate net downtime
    total_seconds = 0.0
    for start, end in filtered_inc:
        span = (end - start).total_seconds()
        for m_start, m_end in merged_maint:
            lo = max(start, m_start)
            hi = min(end, m_end)
            span -= max((hi - lo).total_seconds(), 0.0)
        total_seconds += span

    return total_seconds / 60.0

