newString: """SLA downtime accounting."""
from datetime import datetime, timedelta


def _t(s):
    return datetime.fromisoformat(s)


def subtract_intervals(incident, maintenance_intervals):
    """Subtract maintenance_intervals from a single incident interval.
    Returns a list of remaining disjoint intervals.
    """
    remaining = [incident]
    for m_start, m_end in maintenance_intervals:
        next_remaining = []
        for r_start, r_end in remaining:
            if m_end <= r_start or m_start >= r_end:
                # No overlap
                next_remaining.append((r_start, r_end))
            else:
                # Overlap
                if m_start > r_start:
                    next_remaining.append((r_start, m_start))
                if m_end < r_end:
                    next_remaining.append((m_end, r_end))
        remaining = next_remaining
    return remaining


def downtime_minutes(incidents, maintenance):
    """Total SLA downtime in minutes for a billing period."""
    # 1. Parse valid maintenance windows (must be announced >= 24 hours prior)
    valid_maintenance = []
    for m in maintenance:
        start_dt = _t(m["start"])
        end_dt = _t(m["end"])

        # Check if the announcement was made at least 24 hours before start
        is_late = False
        announced_at_str = m.get("announced_at")
        if announced_at_str:
            announced_at_dt = _t(announced_at_str)
            if start_dt - announced_at_dt < timedelta(hours=24):
                is_late = True

        if not is_late:
            valid_maintenance.append((start_dt, end_dt))

    # 2. Parse and sort incident windows
    parsed_incidents = []
    for inc in incidents:
        parsed_incidents.append((_t(inc["start"]), _t(inc["end"])))

    sorted_incidents = sorted(parsed_incidents, key=lambda x: x[0])

    # 3. Merge overlapping or contiguous incident windows
    merged_incidents = []
    for start, end in sorted_incidents:
        if not merged_incidents:
            merged_incidents.append((start, end))
        else:
            last_start, last_end = merged_incidents[-1]
            if start <= last_end:
                merged_incidents[-1] = (last_start, max(last_end, end))
            else:
                merged_incidents.append((start, end))

    # 4. Filter out sub-minute blips (strictly less than 60 seconds)
    filtered_incidents = []
    for start, end in merged_incidents:
        if (end - start).total_seconds() >= 60.0:
            filtered_incidents.append((start, end))

    # 5. Subtract valid maintenance from the filtered incidents
    total_seconds = 0.0
    for start, end in filtered_incidents:
        remaining = subtract_intervals((start, end), valid_maintenance)
        for r_start, r_end in remaining:
            total_seconds += (r_end - r_start).total_seconds()

    return total_seconds / 60.0
