def advance(order, target):
    """Move an order to `target`, enforcing the lifecycle transition map."""
    cur = str(order["state"]).lower()
    dst = str(target).lower()

    # Track history of transitions inside the order dictionary
    history = order.setdefault("_history", [])
    if not history or history[-1] != cur:
        history.append(cur)

    # Determine if the order was ever paid
    paid_states = {"paid", "shipped", "returned", "refunded"}
    has_been_paid = any(state in paid_states for state in history) or cur in paid_states

    if has_been_paid:
        allowed = _ALLOWED_PAID
    else:
        allowed = _ALLOWED_UNPAID

    if cur not in allowed or dst not in allowed[cur]:
        raise InvalidTransition(str(order["state"]) + " -> " + str(target))

    order["state"] = dst
    # Also append the new state to history
    if not history or history[-1] != dst:
        history.append(dst)

    return order
