    """Merge tag lists from every source into one combined list."""
    first_assertion = {}
    first_assertion_index = {}
    first_tombstone_index = {}
    unique_tags_ordered = []

    for i, tags in enumerate(sources):
        for tag in tags:
            if tag.startswith("-"):
                t_norm = tag[1:].lower()
                if t_norm not in first_tombstone_index:
                    first_tombstone_index[t_norm] = i
            else:
                t_norm = tag.lower()
                if t_norm not in first_assertion:
                    first_assertion[t_norm] = tag
                    first_assertion_index[t_norm] = i
                    unique_tags_ordered.append(t_norm)

    out = []
    for t_norm in unique_tags_ordered:
        a_idx = first_assertion_index[t_norm]
        t_idx = first_tombstone_index.get(t_norm, float('inf'))
        if a_idx < t_idx:
            out.append(first_assertion[t_norm])
    return out

