def parse_quantity(value, kind):
    """Convert a config quantity like '512M' into bytes for the given
    resource kind ("memory" or "disk")."""
    s = str(value).strip()
    if not s:
        raise ValueError("empty quantity")

    if kind == "memory":
        units = {
            "K": 1024,
            "M": 1024 ** 2,
            "G": 1024 ** 3,
            "T": 1024 ** 4
        }
        default_multiplier = 1024 ** 2
    elif kind == "disk":
        units = {
            "M": 1000 ** 2,
            "G": 1000 ** 3,
            "T": 1000 ** 4
        }
        default_multiplier = 1000 ** 3
    else:
        raise ValueError("invalid resource kind: " + str(kind))

    if s[-1].isalpha():
        suffix = s[-1].upper()
        if suffix not in units:
            raise ValueError("invalid unit suffix for " + kind + ": " + s[-1])
        try:
            num = int(s[:-1])
        except ValueError:
            raise ValueError("invalid quantity: " + s)
        return num * units[suffix]

    try:
        num = int(s)
    except ValueError:
        raise ValueError("invalid quantity: " + s)
    return num * default_multiplier
